SCENARIOS = [
    ('health-endpoint', 129, 66, 1550, 300),
    ('report-export',   880,  8,    5, 500),
    ('static-asset',     35, 24,  400, 200),
]

FIX = {
    'THROUGHPUT-bound': 'add concurrency or shed load',
    'LATENCY-bound': 'shorten the path (cache, reuse connections, closer edge)',
    'HEALTHY': 'no network fix warranted',
}

def classify(service_ms, workers, offered_rps, slo_ms):
    service_s = service_ms / 1000.0
    capacity = round(workers / service_s, 1)
    utilization = round(offered_rps / capacity, 2)
    if utilization >= 1.0:
        verdict = 'THROUGHPUT-bound'
    elif service_ms > slo_ms:
        verdict = 'LATENCY-bound'
    else:
        verdict = 'HEALTHY'
    return capacity, utilization, verdict

for name, service_ms, workers, offered_rps, slo_ms in SCENARIOS:
    capacity, utilization, verdict = classify(service_ms, workers, offered_rps, slo_ms)
    print(f'{name}: service={service_ms}ms workers={workers} offered={offered_rps}rps')
    print(f'  capacity={capacity}rps utilization={utilization} -> {verdict}')
    print(f'  fix class: {FIX[verdict]}')
    if utilization >= 1.0:
        print(f'  queue grows without bound — p99 is queue time, not service time')

