def authoritative(t):
    return ('10.2.4.9', 600) if t < 100 else ('10.2.9.30', 300)

QUERIES = [
    (10,  'resolver-A'),
    (80,  'resolver-B'),
    (120, 'resolver-A'),
    (150, 'resolver-C'),
    (400, 'resolver-B'),
    (700, 'resolver-B'),
]

OLD_IP = '10.2.4.9'
caches = {}

def resolve(resolver, t):
    slot = caches.get(resolver)
    if slot is not None:
        ip, fetched_at, ttl = slot
        if t < fetched_at + ttl:
            return ip, 'cache'
    ip, ttl = authoritative(t)
    caches[resolver] = (ip, t, ttl)
    return ip, 'auth'

for t, r in QUERIES:
    ip, how = resolve(r, t)
    stale = ' STALE' if (t >= 100 and ip == OLD_IP) else ''
    print(f't={t:<4} {r} -> {ip} ({how}){stale}')

for r in sorted(caches):
    ip, fetched_at, ttl = caches[r]
    if ip == OLD_IP:
        print(f'{r} heals at t={fetched_at + ttl} (cached old ip at t={fetched_at}, ttl={ttl})')

