    ('expired-intermediate', [
        {'subject': 'service.example.com', 'issuer': 'R3 Intermediate', 'expired': False},
        {'subject': 'R3 Intermediate', 'issuer': 'ISRG Root X1', 'expired': True}]),
    ('wrong-host', [
        {'subject': 'other.example.net', 'issuer': 'R3 Intermediate', 'expired': False},
        {'subject': 'R3 Intermediate', 'issuer': 'ISRG Root X1', 'expired': False}]),
]

def verify_chain(hostname, presented, trust_store):
    if presented[0]['subject'] != hostname:
        return 'FAIL name-mismatch'
    for i, cert in enumerate(presented):
        if cert['expired']:
            return f"FAIL expired ({cert['subject']})"
        nxt = presented[i + 1] if i + 1 < len(presented) else None
        if nxt is not None and cert['issuer'] == nxt['subject']:
            continue
        if cert['issuer'] in trust_store:
            return f"OK (chain of {i + 1} certs anchors at {cert['issuer']})"
        return f"FAIL missing-link (nothing presents {cert['issuer']})"
    return 'FAIL untrusted-terminus'

for name, presented in CONFIGS:
    print(f'{name}: {verify_chain("service.example.com", presented, TRUST_STORE)}')

