RTT_MS = 80
SEGMENTS = [
    ('mobile',     0.55, True,  0.40),
    ('office',     0.33, True,  0.25),
    ('enterprise', 0.12, False, 0.00),
]

def h3_mean_ms(resume_rate):
    return (1 - resume_rate) * RTT_MS

def evaluate_rollout(rollout):
    reachable = 0.0
    weighted = 0.0
    for name, share, udp_open, resume_rate in SEGMENTS:
        if udp_open:
            reachable += share
            weighted += share * h3_mean_ms(resume_rate)
        elif rollout == 'dual-stack':
            reachable += share
            weighted += share * (2 * RTT_MS)
    mean = weighted / reachable if reachable else 0.0
    return round(reachable * 100, 1), round(mean, 1)

for name, share, udp_open, resume_rate in SEGMENTS:
    if udp_open:
        path = f'h3 fresh={RTT_MS}ms resumed=0ms mean={h3_mean_ms(resume_rate):.1f}ms'
    else:
        path = f'UDP blocked: h3-only=UNREACHABLE dual=tcp+tls {2*RTT_MS}ms'
    print(f'{name:<10} share={share:.2f} {path}')

r1, m1 = evaluate_rollout('h3-only')
r2, m2 = evaluate_rollout('dual-stack')
print(f'h3-only:    reachability={r1}% weighted-handshake={m1}ms')
print(f'dual-stack: reachability={r2}% weighted-handshake={m2}ms')
if r2 > r1:
    print(f'decision: dual-stack — {m2 - m1:.1f}ms weighted cost buys back {r2 - r1:.1f}% of clients')

