PLAN = ['10.20.0.0/20', '10.20.16.0/20', '10.20.32.0/20', '10.20.48.0/22']
PEERS = [('on-prem', '10.10.0.0/16'), ('partner', '10.1.0.0/16'), ('legacy-vpc', '10.20.40.0/21')]

def to_int(ip):
    a, b, c, d = (int(x) for x in ip.split('.'))
    return (a << 24) | (b << 16) | (c << 8) | d

def to_str(n):
    return f'{(n >> 24) & 255}.{(n >> 16) & 255}.{(n >> 8) & 255}.{n & 255}'

def cidr_info(cidr):
    ip, prefix = cidr.split('/')
    prefix = int(prefix)
    size = 1 << (32 - prefix)
    network = to_int(ip) & ~(size - 1) & 0xFFFFFFFF
    return network, network + 1, network + size - 2, size - 2

def broadcast(cidr):
    ip, prefix = cidr.split('/')
    size = 1 << (32 - int(prefix))
    return (to_int(ip) & ~(size - 1) & 0xFFFFFFFF) + size - 1

def overlaps(a, b):
    net_a, _, _, _ = cidr_info(a)
    net_b, _, _, _ = cidr_info(b)
    return net_a <= broadcast(b) and net_b <= broadcast(a)

for cidr in PLAN:
    net, first, last, usable = cidr_info(cidr)
    print(f'{cidr:<15} network={to_str(net):<12} usable={to_str(first)}..{to_str(last)} count={usable}')

found = 0
pairs = [(a, f'peer:{name}', p) for a in PLAN for name, p in PEERS] + \
        [(PLAN[i], f'plan:{PLAN[j]}', PLAN[j]) for i in range(len(PLAN)) for j in range(i + 1, len(PLAN))]
for a, label, b in pairs:
    if overlaps(a, b):
        found += 1
        print(f'OVERLAP: {a} intersects {label} ({b})')
if found == 0:
    print('all clear: no overlaps')
else:
    print(f'{found} overlap(s) — plan is NOT safe to peer')

