CLIENT_TABLE = [
    ('10.20.0.0/16', 'local'),
    ('0.0.0.0/0',    'nat-gw'),
]
SERVICE_TABLE = [
    ('10.20.0.0/20',  'local'),
    ('10.20.32.0/20', 'local'),
    ('0.0.0.0/0',     'firewall-appliance'),
]

FLOWS = [
    ('az-a-client', '10.20.16.7', '10.20.0.5', '10.20.16.0/20'),
    ('az-b-client', '10.20.32.9', '10.20.0.5', '10.20.32.0/20'),
    ('external',    '203.0.113.50', '10.20.0.5', None),
]

def to_int(ip):
    a, b, c, d = (int(x) for x in ip.split('.'))
    return (a << 24) | (b << 16) | (c << 8) | d

def lpm(table, ip):
    ip_int = to_int(ip)
    best_prefix, best_hop = -1, 'unreachable'
    for cidr, hop in table:
        net, prefix = cidr.split('/')
        prefix = int(prefix)
        size = 1 << (32 - prefix)
        network = to_int(net) & ~(size - 1) & 0xFFFFFFFF
        if network <= ip_int < network + size and prefix > best_prefix:
            best_prefix, best_hop = prefix, hop
    return best_hop

repairs = []
for name, client_ip, service_ip, client_cidr in FLOWS:
    fwd = lpm(CLIENT_TABLE, service_ip)
    ret = lpm(SERVICE_TABLE, client_ip)
    if fwd == 'local' and ret == 'local':
        print(f'{name}: fwd={fwd} ret={ret} -> SYMMETRIC')
    else:
        print(f'{name}: fwd={fwd} ret={ret} -> ASYMMETRIC (reply exits via {ret})')
        if client_cidr:
            repairs.append((name, client_cidr))

for name, cidr in repairs:
    print(f'repair for {name}: add ({cidr} -> local) to the service subnet route table')

