BACKENDS = [
    ('b1', True, 200),
    ('b2', True, 200),
    ('b3', True, 500),
    ('b4', True, 500),
    ('b5', True, 200),
]

def build_pool(backends, mode):
    pool = []
    for name, tcp_open, status in backends:
        if mode == 'L4' and tcp_open:
            pool.append(name)
        elif mode == 'L7' and tcp_open and status == 200:
            pool.append(name)
    return pool

def error_rate(backends, pool):
    if not pool:
        return 100.0
    status = {name: s for name, _, s in backends}
    bad = sum(1 for name in pool if status[name] != 200)
    return round(bad / len(pool) * 100, 1)

for name, tcp_open, status in BACKENDS:
    l4 = 'pass' if tcp_open else 'fail'
    l7 = 'pass' if (tcp_open and status == 200) else 'FAIL'
    print(f'{name}: tcp={"open" if tcp_open else "closed"} http={status} L4={l4} L7={l7}')

for mode in ('L4', 'L7'):
    pool = build_pool(BACKENDS, mode)
    rate = error_rate(BACKENDS, pool)
    print(f'{mode}: pool={pool} error_rate={rate}%')

l4_rate = error_rate(BACKENDS, build_pool(BACKENDS, 'L4'))
print(f'verdict: L4 mode explains the incident — TCP checks keep dead apps pooled ({l4_rate}% of requests hit a corpse)')

