def to_int(ip):
    a, b, c, d = (int(x) for x in ip.split('.'))
    return (a << 24) | (b << 16) | (c << 8) | d

def cidr_contains(cidr, ip):
    net, prefix = cidr.split('/')
    size = 1 << (32 - int(prefix))
    network = to_int(net) & ~(size - 1) & 0xFFFFFFFF
    return network <= to_int(ip) < network + size

def can_reach(src, dst, port):
