def search_list(ns):
    return [f'{ns}.svc.cluster.local', 'svc.cluster.local', 'cluster.local']

def resolve_name(name, ns, ndots=5):
    if name.count('.') < ndots:
        candidates = [f'{name}.{s}' for s in search_list(ns)] + [name]
    else:
        candidates = [name] + [f'{name}.{s}' for s in search_list(ns)]
    tried = []
    for cand in candidates:
        tried.append(cand)
        if cand in ZONE:
            return ZONE[cand], tried
    return None, tried

