PODS = [
    {'name': 'checkout-7d4', 'labels': {'app': 'checkout', 'tier': 'wep'}, 'ready': True},
    {'name': 'checkout-9k2', 'labels': {'app': 'checkout', 'tier': 'wep'}, 'ready': True},
    {'name': 'catalog-3fa',  'labels': {'app': 'catalog', 'tier': 'web'}, 'ready': True},
    {'name': 'catalog-8xz',  'labels': {'app': 'catalog', 'tier': 'web'}, 'ready': False},
]
SERVICES = {
    'checkout-svc': {'selector': {'app': 'checkout', 'tier': 'web'}},
    'catalog-svc':  {'selector': {'app': 'catalog', 'tier': 'web'}},
}
INGRESS = [
    {'host': 'api.example.com', 'path': '/checkout', 'service': 'checkout-svc'},
    {'host': 'api.example.com', 'path': '/catalog',  'service': 'catalog-svc'},
]
REQUESTS = [
    ('api.example.com', '/checkout'),
    ('api.example.com', '/catalog'),
    ('api.example.com', '/payments'),
    ('shop.example.com', '/catalog'),
]

def compute_endpoints(service, pods):
    eps = []
    for pod in pods:
        if not pod['ready']:
            continue
        if all(pod['labels'].get(k) == v for k, v in service['selector'].items()):
            eps.append(pod['name'])
    return eps

def route_request(host, path):
    rule = next((r for r in INGRESS if r['host'] == host and path.startswith(r['path'])), None)
    if rule is None:
        return '404', 'no ingress rule'
    svc = SERVICES.get(rule['service'])
    if svc is None:
        return '503', 'service missing'
    eps = compute_endpoints(svc, PODS)
    if not eps:
        return '503', 'no endpoints (selector matches 0 pods)'
    return '200', f'served by {eps[0]}'

for name, svc in SERVICES.items():
    eps = compute_endpoints(svc, PODS)
    print(f'{name}: endpoints={eps if eps else "<none>"}')

for host, path in REQUESTS:
    code, reason = route_request(host, path)
    print(f'{host}{path} -> {code} ({reason})')

