PODS = {
    'api-1':      {'ns': 'api',      'labels': {'app': 'api'}},
    'smoke':      {'ns': 'api',      'labels': {'role': 'smoke-test'}},
    'payments-1': {'ns': 'payments', 'labels': {'role': 'payments'}},
    'debug':      {'ns': 'default',  'labels': {'role': 'debug'}},
}

POLICY_V1 = [{
    'ns': 'api', 'pod_selector': {'app': 'api'},
    'allows': [{'ns': None, 'pod_labels': {'role': 'smoke-test'}, 'port': 8080}],
}]

PAYMENTS_DOOR = {'ns': 'payments', 'pod_labels': {'role': 'payments'}, 'port': 8080}

FLOWS = [('smoke', 'api-1', 8080), ('payments-1', 'api-1', 8080), ('debug', 'api-1', 8080)]

def labels_contain(pod_labels, wanted):
    return all(pod_labels.get(k) == v for k, v in wanted.items())

def evaluate_flow(src, dst, port, policies):
    s, d = PODS[src], PODS[dst]
    selecting = [p for p in policies if p['ns'] == d['ns'] and labels_contain(d['labels'], p['pod_selector'])]
    if not selecting:
        return 'ALLOW', 'no policy selects the pod (open by default)'
    for p in selecting:
        for i, allow in enumerate(p['allows']):
            src_ns_ok = (allow['ns'] is None and s['ns'] == d['ns']) or (allow['ns'] == s['ns'])
            if src_ns_ok and labels_contain(s['labels'], allow['pod_labels']) and port == allow['port']:
                return 'ALLOW', f'door: allow[{i}] ns={allow["ns"] or "same"} labels={allow["pod_labels"]}'
    return 'DENY', 'selected + no matching allow (silent drop)'

print('v1 (before the payments door):')
for src, dst, port in FLOWS:
    verdict, reason = evaluate_flow(src, dst, port, POLICY_V1)
    print(f'  {src} -> {dst}:{port} = {verdict} ({reason})')

