def diff_taps(lb, pod):
    lb_srcs = {src for src, _ in lb}
    pod_srcs = {src for src, _ in pod}
    crossed = sorted(lb_srcs & pod_srcs)
    died = sorted(lb_srcs - pod_srcs)
    return crossed, died

def shared_prefix(ips):
    if not ips:
        return ''
    split = [ip.split('.') for ip in ips]
    prefix = []
    for parts in zip(*split):
        if len(set(parts)) == 1:
            prefix.append(parts[0])
        else:
            break
    return '.'.join(prefix)

crossed, died = diff_taps(LB_TAP, POD_TAP)
print(f'tap LB: {len(LB_TAP)} flows | tap pod: {len(POD_TAP)} flows')
print(f'crossed the edge: {len(crossed)}')
print(f'died on the edge: {len(died)}')
for src in died:
    print(f'  dead flow: src={src}')
fp = shared_prefix(died)
print(f'fingerprint: dead flows share prefix {fp}.* — the drop selects this source range')

