RULES_V1 = [
    (10, 'ALLOW', 443, '10.8.0.0/16'),
    (20, 'DENY',  None, '172.16.0.0/12'),
    (30, 'ALLOW', 443, '172.20.0.0/16'),
    (99, 'DENY',  None, '0.0.0.0/0'),
]

FLOWS = [
    ('vpn-client',   '10.8.3.7',    443),
    ('region-b',     '172.20.4.9',  443),
    ('legacy-host',  '172.16.99.9', 443),
    ('internet',     '203.0.113.77', 443),
]

def to_int(ip):
    a, b, c, d = (int(x) for x in ip.split('.'))
    return (a << 24) | (b << 16) | (c << 8) | d

def cidr_bounds(cidr):
    net, prefix = cidr.split('/')
    size = 1 << (32 - int(prefix))
    network = to_int(net) & ~(size - 1) & 0xFFFFFFFF
    return network, network + size - 1

def cidr_contains_ip(cidr, ip):
    lo, hi = cidr_bounds(cidr)
    return lo <= to_int(ip) <= hi

def cidr_contains_cidr(outer, inner):
    olo, ohi = cidr_bounds(outer)
    ilo, ihi = cidr_bounds(inner)
    return olo <= ilo and ihi <= ohi

def match_flow(rules, src_ip, port):
    for rid, action, rport, cidr in rules:
        if (rport is None or rport == port) and cidr_contains_ip(cidr, src_ip):
            return rid, action
    return None, 'DENY'

def find_shadowed(rules):
    shadowed = []
    for i, (rid, action, rport, cidr) in enumerate(rules):
        for erid, eaction, erport, ecidr in rules[:i]:
            if (erport is None or erport == rport) and cidr_contains_cidr(ecidr, cidr):
                shadowed.append((rid, erid))
                break
    return shadowed

print('v1 verdicts:')
for name, ip, port in FLOWS:
    rid, action = match_flow(RULES_V1, ip, port)
    print(f'  {name} ({ip}:{port}) -> rule {rid}: {action}')

print('shadow report:')
for rid, erid in find_shadowed(RULES_V1):
    print(f'  rule {rid} is SHADOWED by earlier rule {erid} — dead code')

repaired = [RULES_V1[0], RULES_V1[2], RULES_V1[1], RULES_V1[3]]
print('after repair (specific allow moved above broad deny):')
for name, ip, port in FLOWS:
    rid, action = match_flow(repaired, ip, port)
    print(f'  {name} ({ip}:{port}) -> rule {rid}: {action}')

