CALLERS = [
    {'name': 'billing',  'san': 'spiffe://cluster/ns/billing/sa/billing',  'cert_valid': True,  'ca': 'mesh-ca'},
    {'name': 'reports',  'san': 'spiffe://cluster/ns/reports/sa/reports', 'cert_valid': True,  'ca': 'mesh-ca'},
    {'name': 'batch',    'san': 'spiffe://cluster/ns/batch/sa/batch',     'cert_valid': False, 'ca': 'mesh-ca'},
    {'name': 'intruder', 'san': 'spiffe://cluster/ns/billing/sa/billing', 'cert_valid': True,  'ca': 'self-signed'},
]

def check_access(caller):
    if caller['ca'] != TRUSTED_CA:
        return 'DENY', 'identity: untrusted CA'
    if not caller['cert_valid']:
        return 'DENY', 'identity: certificate expired'
    if caller['san'] not in POLICY:
        return 'DENY', 'authz: principal not in policy'
    return 'ALLOW', 'all gates passed'

gate_denials = {'identity': 0, 'authz': 0}
for caller in CALLERS:
    verdict, detail = check_access(caller)
    print(f"{caller['name']}: {verdict} ({detail})")
    if verdict == 'DENY':
        gate_denials[detail.split(':')[0]] += 1

print(f"denials at identity gate: {gate_denials['identity']}")
print(f"denials at authz gate: {gate_denials['authz']}")
print('localization: authz denials with clean handshakes mean policy strings, not certificates')
